@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Course Catalog — Browse Courses</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<div class="card mb-4 shadow-sm">
    <div class="card-body">
        <div class="row g-3 align-items-end">
            <div class="col-md-5">
                <label for="search" class="form-label">Search</label>
                <input id="search" type="text" class="form-control" placeholder="Search by title, code, or keyword…"
                       @bind="searchTerm" @bind:event="oninput" />
            </div>
            <div class="col-md-3">
                <label for="dept" class="form-label">Department</label>
                <select id="dept" class="form-select" @bind="selectedDepartment">
                    <option value="0">All Departments</option>
                    @foreach (var dept in departments)
                    {
                        <option value="@dept.Id">@dept.Name</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="credits" class="form-label">Credits</label>
                <select id="credits" class="form-select" @bind="selectedCredits">
                    <option value="0">Any</option>
                    <option value="3">3 credits</option>
                    <option value="4">4 credits</option>
                </select>
            </div>
            <div class="col-md-2">
                <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
            </div>
        </div>
    </div>
</div>

<p class="text-muted mb-3">Showing @filteredCourses.Count course(s)</p>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try broadening your filters.</div>
}
else
{
    <div class="row g-3">
        @foreach (var course in filteredCourses)
        {
            var dept = Catalog.GetDepartment(course.DepartmentId);
            var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
            <div class="col-md-6 col-lg-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body d-flex flex-column">
                        <div class="d-flex justify-content-between mb-2">
                            <span class="badge bg-primary">@dept?.Code</span>
                            <span class="badge @(spotsLeft > 10 ? "bg-success" : spotsLeft > 0 ? "bg-warning text-dark" : "bg-danger")">
                                @(spotsLeft > 0 ? $"{spotsLeft} spots left" : "Full")
                            </span>
                        </div>
                        <h5 class="card-title">@course.Code</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                        <p class="card-text small flex-grow-1">@Truncate(course.Description, 100)</p>
                        <div class="d-flex justify-content-between align-items-center mt-auto">
                            <small class="text-muted">@course.Credits cr · @course.Schedule</small>
                        </div>
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm mt-2">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<Department> departments = [];
    private List<Course> filteredCourses = [];

    private string _searchTerm = string.Empty;
    private int _selectedDepartment;
    private int _selectedCredits;

    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int selectedDepartment
    {
        get => _selectedDepartment;
        set { _selectedDepartment = value; ApplyFilters(); }
    }

    private int selectedCredits
    {
        get => _selectedCredits;
        set { _selectedCredits = value; ApplyFilters(); }
    }

    [SupplyParameterFromQuery(Name = "department")]
    private int? QueryDepartment { get; set; }

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();

        if (QueryDepartment.HasValue)
            _selectedDepartment = QueryDepartment.Value;

        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = Catalog.SearchCourses(
            _searchTerm,
            _selectedDepartment > 0 ? _selectedDepartment : null,
            _selectedCredits > 0 ? _selectedCredits : null);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartment = 0;
        _selectedCredits = 0;
        ApplyFilters();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "…");
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@rendermode InteractiveServer

<PageTitle>Enrollment Request — Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@model.FullName</strong>. Your enrollment request for
            <strong>@(Catalog.GetCourse(model.CourseId)?.Title)</strong> has been received.</p>
        <p>You will receive a confirmation at <strong>@model.Email</strong>.</p>
        <hr />
        <a href="/courses" class="btn btn-outline-success">Browse More Courses</a>
        <button class="btn btn-outline-primary ms-2" @onclick="ResetForm">Submit Another Request</button>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card shadow-sm">
                <div class="card-body">
                    <p class="text-muted mb-4">Fill out the form below to request enrollment in a course.
                        All fields marked with <span class="text-danger">*</span> are required.</p>

                    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm">
                        <DataAnnotationsValidator />
                        <ValidationSummary class="text-danger mb-3" />

                        <div class="mb-3">
                            <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
                            <InputText id="fullName" class="form-control" @bind-Value="model.FullName" placeholder="e.g. Jane Doe" />
                            <ValidationMessage For="() => model.FullName" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                            <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g. STU123456" />
                            <ValidationMessage For="() => model.StudentId" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
                            <InputText id="email" class="form-control" @bind-Value="model.Email" placeholder="e.g. jane.doe@university.edu" />
                            <ValidationMessage For="() => model.Email" class="text-danger" />
                        </div>

                        <div class="mb-3">
