toolArgs.file_text:
@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@rendermode InteractiveServer

<PageTitle>Enrollment Request — Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@model.FullName</strong>. Your enrollment request for
            <strong>@(Catalog.GetCourse(model.CourseId)?.Title)</strong> has been received.</p>
        <p>You will receive a confirmation at <strong>@model.Email</strong>.</p>
        <hr />
        <a href="/courses" class="btn btn-outline-success">Browse More Courses</a>
        <button class="btn btn-outline-primary ms-2" @onclick="ResetForm">Submit Another Request</button>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card shadow-sm">
                <div class="card-body">
                    <p class="text-muted mb-4">Fill out the form below to request enrollment in a course.
                        All fields marked with <span class="text-danger">*</span> are required.</p>

                    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm">
                        <DataAnnotationsValidator />
                        <ValidationSummary class="text-danger mb-3" />

                        <div class="mb-3">
                            <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
                            <InputText id="fullName" class="form-control" @bind-Value="model.FullName" placeholder="e.g. Jane Doe" />
                            <ValidationMessage For="() => model.FullName" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                            <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g. STU123456" />
                            <ValidationMessage For="() => model.StudentId" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
                            <InputText id="email" class="form-control" @bind-Value="model.Email" placeholder="e.g. jane.doe@university.edu" />
                            <ValidationMessage For="() => model.Email" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="courseSelect" class="form-label">Course <span class="text-danger">*</span></label>
                            <InputSelect id="courseSelect" class="form-select" @bind-Value="model.CourseId">
                                <option value="0">— Select a course —</option>
                                @foreach (var course in courses)
                                {
                                    var dept = Catalog.GetDepartment(course.DepartmentId);
                                    <option value="@course.Id">@course.Code — @course.Title (@dept?.Code)</option>
                                }
                            </InputSelect>
                            <ValidationMessage For="() => model.CourseId" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="comments" class="form-label">Comments (optional)</label>
                            <InputTextArea id="comments" class="form-control" @bind-Value="model.Comments" rows="3"
                                           placeholder="Any additional information or special requests…" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                        <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                    </EditForm>
                </div>
            </div>
        </div>

        <div class="col-lg-4">
            <div class="card shadow-sm bg-light">
                <div class="card-body">
                    <h5 class="card-title">How It Works</h5>
                    <ol class="mb-0">
                        <li class="mb-2">Fill in your details and select a course.</li>
                        <li class="mb-2">Submit the enrollment request form.</li>
                        <li class="mb-2">The registrar's office will review your request.</li>
                        <li>You'll receive confirmation via email within 2 business days.</li>
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private EnrollmentRequest model = new();
    private List<Course> courses = [];
    private bool submitted;

    [SupplyParameterFromQuery(Name = "course")]
    private int? PreselectedCourseId { get; set; }

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();
        if (PreselectedCourseId.HasValue)
            model.CourseId = PreselectedCourseId.Value;
    }

    private void HandleSubmit()
    {
        Catalog.SubmitEnrollmentRequest(model);
        submitted = true;
    }

    private void ResetForm()
    {
        model = new EnrollmentRequest();
        submitted = false;
    }
}

